/**
 * Expo UI theme — native SwiftUI / Material mappings.
 * Master switch: appSetting('native', 'expo_ui_buttons') in settings/configs.js.
 * Read button config: appSetting('theme', 'expo_ui', 'button').
 */
export const settingsExpoUi = {
    expo_ui: {
        // Icon glyphs on iOS for Expo UI buttons and NativeTabs (like una-ios
        // SF Pro / Custom):
        //   'lucide' — the app's Lucide set from the native asset catalog
        //              (`Lucide/<kebab>`, generated by apps/expo/plugins/
        //              with-lucide-assets.js), tinted like SF Symbols.
        //   'sf'     — SF Symbols via `button.iosSymbols` / `tabs.icons`.
        // Each falls back to the other when a glyph is missing; a button's
        // `systemImage` always renders that SF Symbol.
        iosIconSource: 'lucide',
        // Icon glyphs on Android for NativeTabs:
        //   'lucide'   — the app's Lucide set as vector drawables
        //                (`lucide_<snake>`, same plugin), tinted by Material.
        //   'material' — Material Symbols via `tabs.icons[…].md`.
        // Lucide falls back to Material when a glyph has no drawable.
        androidIconSource: 'lucide',
        // Long-press, labelled custom children, glyphs with no native asset,
        // and selected on non-glass styles stay JS-styled (Android: also
        // unmapped icons and any custom children; iOS hosts icon-like
        // children such as the header logo). Unselected glass has no tint so
        // iOS can invert label/icon color. Selected glass stays Expo UI
        // `.plain` + `glassEffect` tint from iosColors.glass.selected
        // (`bg-accent` wash + `text-accent-foreground` label). Addon counters
        // render as a SwiftUI child on glass — they do not fall back to JS.
        button: {
            styles: true,
            androidVariants: {
                plain: 'text',
                borderless: 'text',
                link: 'text',
                bordered: 'tonal',
                borderedProminent: 'filled',
                glass: 'elevated',
                glassProminent: 'filled',
            },
            // Hex, or a theme class (`bg-*` / `text-*`) resolved to hex through
            // Uniwind — raw CSS variables do not resolve inside a native Host.
            // Classes follow the tokens in light / dark and in branch themes,
            // and match the JS styles in buttons.js. Palettes are flat, or
            // `{ default, dark }` for scheme-specific hex. `tinted*` / `selected`
            // is the toggled look: `bg-accent` + `text-accent-foreground`.
            androidColors: {
                tonal: {
                    containerColor: 'bg-button',
                    contentColor: 'text-button-foreground',
                    tintedContainerColor: 'bg-accent',
                    tintedContentColor: 'text-accent-foreground',
                },
                elevated: {
                    containerColor: 'bg-button',
                    contentColor: 'text-button-foreground',
                    tintedContainerColor: 'bg-accent',
                    tintedContentColor: 'text-accent-foreground',
                },
                text: { contentColor: 'text-card-foreground' },
                filled: { containerColor: 'bg-primary', contentColor: 'text-primary-foreground' },
            },
            iosTint: null,
            // Same value rules as `androidColors` (hex or a `bg-*` / `text-*` class).
            iosColors: {
                bordered: {
                    tint: 'bg-button',
                    foreground: 'text-button-foreground',
                    selected: { tint: 'bg-accent', foreground: 'text-accent-foreground' },
                },
                plain: { tint: 'text-card-foreground' },
                borderless: { tint: 'text-card-foreground' },
                glass: {
                    // Resting: no tint — label/icon invert over dark content.
                    // Selected: tint = liquid-glass wash, foreground = label/icon,
                    // from the accent tokens (light and dark alike).
                    // iOS applies tint via `glassEffect`, not `.glassProminent`.
                    selected: { tint: 'bg-accent', foreground: 'text-accent-foreground' },
                },
                link: { tint: 'text-accent-foreground' },
                borderedProminent: { tint: 'bg-primary' },
                glassProminent: { tint: 'bg-primary' },
            },
            // Native label type. Null still applies size/weight from
            // `neo_button.controlSizes.*.font` and style text (`font-medium`).
            // Override: { size: 15, weight: 'semibold', family: 'Inter' }
            // (`family` is a PostScript name — not CSS `font-main`).
            iosFont: null,
            // Glyph size follows `neo_button.controlSizes.*.icon` (same as web
            // and Android). Override only to pin iOS: a point size, or scoped
            // per NeoButton controlSize (mini … xlarge, not SwiftUI's
            // extraLarge), e.g. { small: 18, regular: 22 }.
            iosIconSize: null,
            iosControlSize: null,
            // Discrete SF Symbol effect on press (iOS 17+). `false` to disable.
            // Per-icon override: `{ name: 'bell.fill', effect: 'wiggle' }`.
            iosSymbolEffect: { effect: 'bounce' },
            iosSymbols: {
                Plus: 'plus',
                X: 'xmark',
                ChevronLeft: 'chevron.left',
                ChevronRight: 'chevron.right',
                ChevronUp: 'chevron.up',
                ChevronDown: 'chevron.down',
                ChevronsUpDown: 'chevron.up.chevron.down',
                ArrowLeft: 'arrow.left',
                ArrowRight: 'arrow.right',
                Search: 'magnifyingglass',
                Ellipsis: 'ellipsis',
                Pencil: 'pencil',
                Trash: 'trash',
                Check: 'checkmark',
                Image: 'photo',
                ImagePlus: 'photo.badge.plus',
                Paperclip: 'paperclip',
                ChartBarBig: 'chart.bar',
                Video: 'video',
                Film: 'film',
                File: 'doc',
                FileText: 'text.page',
                Calendar: 'calendar',
                CalendarPlus: 'calendar.badge.plus',
                List: 'list.bullet',
                ListChecks: 'checklist',
                CheckSquare: 'checkmark.square',
                CircleStar: 'star.circle',
                MessageCircleMore: 'message',
                MessagesSquare: 'bubble.left.and.text.bubble.right',
                Share2: 'square.and.arrow.up',
                SendHorizontal: 'paperplane',
                Send: 'paperplane',
                ScrollText: 'scroll',
                Hash: 'number',
                Info: 'info.circle',
                Clock: 'clock',
                Cog: 'gearshape',
                UserRound: 'person',
                UsersRound: 'person.2',
                UserPlus: 'person.badge.plus',
                Building2: 'building.2',
                Store: 'cart',
                LibraryBig: 'books.vertical',
                LayoutDashboard: 'square.grid.2x2',
                Wallet: 'wallet.pass',
                LogOut: 'rectangle.portrait.and.arrow.right',
                Wand: 'wand.and.stars',
                SquareStack: 'square.stack',
                Clipboard: 'doc.on.clipboard',
                RotateCw: 'arrow.clockwise',
                Award: 'rosette',
                BadgeCheck: 'checkmark.seal',
                House: 'house',
                Bell: 'bell',
                Compass: 'safari',
                Contact: 'person.crop.circle',
            },
            androidIcons: null,
        },
        tabs: {
            // More opens a native sheet listing every route (tab routes,
            // divider, overflow): iOS a Liquid Glass sheet in place of the tab
            // bar, like Revolut / Linear; Android a Material 3 modal bottom
            // sheet. false = the JS popup.
            more_sheet: true,
            // Tab urls left out of the native sheet — its last rows sit where
            // the tab bar was, so keep destructive actions out of that spot.
            // A `{profile}` item at the More slot (settings/menus.js) shows as
            // the avatar and heads the sheet; if it is the only More link left,
            // the avatar opens the profile directly.
            more_sheet_exclude: ['/logout'],
            // NativeTabs (UITabBar / Material 3): Lucide → SF Symbol + MD icon.
            // iOS uses these SF names only when `iosIconSource` is 'sf' or the
            // Lucide asset is missing; Android uses `md` only when
            // `androidIconSource` is 'material' or the Lucide drawable is missing.
            // `selected` is the filled variant. Unlisted icons fall back to button.iosSymbols.
            icons: {
                House: { sf: { default: 'house', selected: 'house.fill' }, md: 'home' },
                UsersRound: { sf: { default: 'person.2', selected: 'person.2.fill' }, md: 'group' },
                MessageCircleMore: { sf: { default: 'message', selected: 'message.fill' }, md: 'chat' },
                Bell: { sf: { default: 'bell', selected: 'bell.fill' }, md: 'notifications' },
                Award: { sf: { default: 'rosette', selected: 'rosette.fill' }, md: 'military_tech' },
                CircleGauge: { sf: { default: 'gauge.with.dots.needle.50percent', selected: 'gauge.with.dots.needle.50percent' }, md: 'speed' },
                Compass: { sf: { default: 'safari', selected: 'safari.fill' }, md: 'explore' },
                Info: { sf: { default: 'info.circle', selected: 'info.circle.fill' }, md: 'info' },
                Contact: { sf: { default: 'person.crop.circle', selected: 'person.crop.circle.fill' }, md: 'contacts' },
                User: { sf: { default: 'person.crop.circle', selected: 'person.crop.circle.fill' }, md: 'account_circle' },
                LayoutDashboard: { sf: { default: 'square.grid.2x2', selected: 'square.grid.2x2.fill' }, md: 'dashboard' },
                ChevronsUpDown: { sf: { default: 'chevron.up.chevron.down', selected: 'chevron.up.chevron.down' }, md: 'unfold_more' },
            },
        },
    },
};
